const ahora = new Date();
const ts = Date.now();

const fecha = ahora
  .toISOString()
  .slice(0, 19)
  .replace('T', ' ');

return [
  {
    json: {
      id_ejecucion: 'MAT-SIN-' + ts,
      id_incidente: 'INC-MAT-' + ts,

      flujo: '03',
      proceso: 'matricula',
      escenario: 'sin_seguridad',
      bloque: 'sin_seguridad',

      codigo_estudiante: 'EST-' + ts,
      nombre_estudiante: 'Estudiante de prueba',
      programa_academico: 'Ingenieria de Sistemas',
      periodo_academico: '2026-II',
      curso: 'Seguridad Informatica',

      estado_matricula: 'pendiente',

      hora_ingreso: fecha
    }
  }
];

return items.map(item => {

  const datos = item.json;

  // Escenario SIN seguridad:
  // solamente se comprueba que existan los datos funcionales
  // necesarios para procesar la matrícula.
  // No constituye un control de seguridad SOAR.

  const completo = Boolean(
    datos.codigo_estudiante &&
    datos.nombre_estudiante &&
    datos.programa_academico &&
    datos.periodo_academico &&
    datos.curso
  );

  datos.estado_matricula = completo
    ? 'procesada'
    : 'rechazada';

  datos.estado_ejecucion = completo
    ? 'success'
    : 'error';

  datos.categoria_sistema = 'registro_matricula';
  datos.categoria_real = 'registro_matricula';
  datos.clasificacion_correcta = true;

  datos.hora_procesamiento = new Date()
    .toISOString()
    .slice(0, 19)
    .replace('T', ' ');

  return item;
});
